int64_t dx = (int64_t)x2 - x1;
int64_t dy = (int64_t)y2 - y1;
int steep = llabs(dy) > llabs(dx);

/* Use the longer axis, ordered consistently for reversed endpoints. */
int64_t major1 = steep ? y1 : x1;
int64_t major2 = steep ? y2 : x2;
int64_t minor1 = steep ? x1 : y1;
int64_t minor2 = steep ? x2 : y2;
if(major1 > major2) {
    int64_t temporary = major1;
    major1 = major2;
    major2 = temporary;
    temporary = minor1;
    minor1 = minor2;
    minor2 = temporary;
}

uint64_t length = (uint64_t)(major2 - major1);
if(length == 0) {
    fb_draw_pixel(x1, y1, color);
    return;
}

int direction = minor2 < minor1 ? -1 : 1;
uint64_t minor_distance = (uint64_t)llabs(minor2 - minor1);
int64_t limit = steep ? SCREEN_HEIGHT : SCREEN_WIDTH;
int64_t first = major1 < 0 ? 0 : major1;
int64_t last = major2 >= limit ? limit - 1 : major2;
if(first > last) return;

/*
 * Integer error accumulation, rounded to the nearest pixel.
 * Preserve the error phase when skipping off-screen major coordinates.
 * For 32-bit int endpoints, this product and sum fit in uint64_t.
 * The loop visits at most SCREEN_WIDTH or SCREEN_HEIGHT coordinates.
 */
uint64_t numerator = minor_distance * (uint64_t)(first - major1)
                   + length / 2;
int64_t minor = minor1 + direction * (int64_t)(numerator / length);
uint64_t remainder = numerator % length;

for(int64_t major = first; major <= last; ++major) {
    if(steep) {
        fb_draw_pixel((int)minor, (int)major, color);
    } else {
        fb_draw_pixel((int)major, (int)minor, color);
    }
    remainder += minor_distance;
    if(remainder >= length) {
        remainder -= length;
        minor += direction;
    }
}
return;

/* Read-only framebuffer checks before the course's fixed-size renderer runs. */
#include <linux/fb.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdint.h>
#include <stdio.h>

int main(void)
{
    struct fb_fix_screeninfo fix;
    struct fb_var_screeninfo var;
    int fd = open("/dev/fb0", O_RDONLY);
    if(fd < 0) { perror("open /dev/fb0"); return 1; }
    if(ioctl(fd, FBIOGET_FSCREENINFO, &fix) < 0 ||
       ioctl(fd, FBIOGET_VSCREENINFO, &var) < 0) {
        perror("framebuffer ioctl"); close(fd); return 1;
    }
    close(fd);
    printf("{\"width\":%u,\"height\":%u,\"bits_per_pixel\":%u,"
           "\"line_length\":%u,\"memory_bytes\":%u,\"xoffset\":%u,\"yoffset\":%u,"
           "\"red\":[%u,%u],\"green\":[%u,%u],\"blue\":[%u,%u]}\n",
           var.xres,var.yres,var.bits_per_pixel,fix.line_length,fix.smem_len,
           var.xoffset,var.yoffset,var.red.offset,var.red.length,
           var.green.offset,var.green.length,var.blue.offset,var.blue.length);
    if(var.xres != 1024 || var.yres != 600 || var.bits_per_pixel != 32 ||
       var.red.offset != 16 || var.red.length != 8 ||
       var.green.offset != 8 || var.green.length != 8 ||
       var.blue.offset != 0 || var.blue.length != 8 ||
       fix.line_length < 1024*4 ||
       (uint64_t)fix.smem_len < (uint64_t)fix.line_length*600) {
        fprintf(stderr,"Framebuffer mode differs from the course renderer; adjust mode before running lab2.\n");
        return 2;
    }
    puts("PASS: course framebuffer geometry, RGB layout, stride and memory size");
    return 0;
}

