                  random_between(-80,SCREEN_WIDTH+80),
                  random_between(-80,SCREEN_HEIGHT+80));
    printf("PASS: eight octants, geometric error, reversed endpoints and extreme clipping\n");
    printf("PASS: %u offline cases\n", tested_cases);
    free(front_storage);
    return 0;
